package com.flippingfriend;
import java.nio.charset.StandardCharsets;import java.nio.file.*;import org.junit.Test;import static org.junit.Assert.*;
public class BuyReplacementIntentPersistenceNonActivationBoundaryTest{@Test public void runtimeDoesNotConsumePersistence()throws Exception{Path r=root();for(String f:new String[]{"companion/src/main/java/com/flippingfriend/companion/CompanionService.java","companion/src/main/java/com/flippingfriend/companion/CompanionMain.java","companion/src/main/java/com/flippingfriend/companion/ApiServer.java","src/main/java/com/flippingfriend/companion/CompanionClient.java","src/main/java/com/flippingfriend/FlippingFriendPlugin.java","src/main/java/com/flippingfriend/model/SuggestionEngine.java"}){String s=Files.readString(r.resolve(f),StandardCharsets.UTF_8);assertFalse(s.contains("buyReplacementIntents"));assertFalse(s.contains("saveBuyReplacementIntent"));}}private static Path root(){Path p=Path.of("").toAbsolutePath();while(p!=null&&!Files.exists(p.resolve("settings.gradle")))p=p.getParent();return p;}}